/* -*- mode: C; c-file-style: "gnu"; indent-tabs-mode: nil; -*- */
/*
 * gnome-session.c: Proxies for the org.gnome.SessionManager D-Bus interfaces.
 * Port of js/misc/gnomeSession.js.
 *
 * The proxies are the ones generated by gdbus-codegen from
 * data/dbus-interfaces/org.gnome.SessionManager*.xml: D-Bus methods are
 * shell_session_manager_*_call_*() functions, properties are GObject
 * properties and D-Bus signals are GObject signals with kebab-case names.
 *
 * SPDX-License-Identifier: GPL-2.0-or-later
 */

#include "config.h"

#include "misc/gnome-session.h"

#define SESSION_MANAGER_BUS_NAME "org.gnome.SessionManager"
#define SESSION_MANAGER_PATH "/org/gnome/SessionManager"
#define PRESENCE_PATH "/org/gnome/SessionManager/Presence"

/**
 * shell_gnome_session_presence_new:
 * @cancellable: (nullable): a #GCancellable
 * @callback: (scope async): called when the proxy is ready
 * @user_data: (closure): user data for @callback
 *
 * Starts creating a proxy for org.gnome.SessionManager.Presence on the
 * session bus. Finish with shell_gnome_session_presence_new_finish().
 */
void
shell_gnome_session_presence_new (GCancellable        *cancellable,
                                  GAsyncReadyCallback  callback,
                                  gpointer             user_data)
{
  shell_session_manager_presence_proxy_new_for_bus (G_BUS_TYPE_SESSION,
                                                    G_DBUS_PROXY_FLAGS_NONE,
                                                    SESSION_MANAGER_BUS_NAME,
                                                    PRESENCE_PATH,
                                                    cancellable,
                                                    callback,
                                                    user_data);
}

/**
 * shell_gnome_session_presence_new_finish:
 * @res: a #GAsyncResult
 * @error: return location for a #GError
 *
 * Returns: (transfer full): the presence proxy, or %NULL with @error set
 */
ShellSessionManagerPresence *
shell_gnome_session_presence_new_finish (GAsyncResult  *res,
                                         GError       **error)
{
  return shell_session_manager_presence_proxy_new_for_bus_finish (res, error);
}

/**
 * shell_gnome_session_manager_new:
 * @cancellable: (nullable): a #GCancellable
 * @callback: (scope async): called when the proxy is ready
 * @user_data: (closure): user data for @callback
 *
 * Starts creating a proxy for org.gnome.SessionManager on the session bus.
 * Finish with shell_gnome_session_manager_new_finish().
 */
void
shell_gnome_session_manager_new (GCancellable        *cancellable,
                                 GAsyncReadyCallback  callback,
                                 gpointer             user_data)
{
  shell_session_manager_proxy_new_for_bus (G_BUS_TYPE_SESSION,
                                           G_DBUS_PROXY_FLAGS_NONE,
                                           SESSION_MANAGER_BUS_NAME,
                                           SESSION_MANAGER_PATH,
                                           cancellable,
                                           callback,
                                           user_data);
}

/**
 * shell_gnome_session_manager_new_finish:
 * @res: a #GAsyncResult
 * @error: return location for a #GError
 *
 * Returns: (transfer full): the session manager proxy, or %NULL with @error set
 */
ShellSessionManager *
shell_gnome_session_manager_new_finish (GAsyncResult  *res,
                                        GError       **error)
{
  return shell_session_manager_proxy_new_for_bus_finish (res, error);
}

/**
 * shell_gnome_session_manager_new_sync:
 * @cancellable: (nullable): a #GCancellable
 * @error: return location for a #GError
 *
 * Creates a proxy for org.gnome.SessionManager on the session bus, blocking
 * until it is ready. Only the methods of the interface that the shell uses
 * are described by the proxy.
 *
 * Returns: (transfer full): the session manager proxy, or %NULL with @error set
 */
ShellSessionManager *
shell_gnome_session_manager_new_sync (GCancellable  *cancellable,
                                      GError       **error)
{
  return shell_session_manager_proxy_new_for_bus_sync (G_BUS_TYPE_SESSION,
                                                       G_DBUS_PROXY_FLAGS_NONE,
                                                       SESSION_MANAGER_BUS_NAME,
                                                       SESSION_MANAGER_PATH,
                                                       cancellable,
                                                       error);
}

/**
 * shell_gnome_session_inhibitor_new:
 * @object_path: the object path of the inhibitor
 * @cancellable: (nullable): a #GCancellable
 * @callback: (scope async): called when the proxy is ready
 * @user_data: (closure): user data for @callback
 *
 * Starts creating a proxy for an org.gnome.SessionManager.Inhibitor on the
 * session bus. Inhibitors are immutable, so the proxy does not need to track
 * changes. Finish with shell_gnome_session_inhibitor_new_finish().
 */
void
shell_gnome_session_inhibitor_new (const char          *object_path,
                                   GCancellable        *cancellable,
                                   GAsyncReadyCallback  callback,
                                   gpointer             user_data)
{
  g_return_if_fail (object_path != NULL);

  shell_session_manager_inhibitor_proxy_new_for_bus (G_BUS_TYPE_SESSION,
                                                     G_DBUS_PROXY_FLAGS_NONE,
                                                     SESSION_MANAGER_BUS_NAME,
                                                     object_path,
                                                     cancellable,
                                                     callback,
                                                     user_data);
}

/**
 * shell_gnome_session_inhibitor_new_finish:
 * @res: a #GAsyncResult
 * @error: return location for a #GError
 *
 * Returns: (transfer full): the inhibitor proxy, or %NULL with @error set
 */
ShellSessionManagerInhibitor *
shell_gnome_session_inhibitor_new_finish (GAsyncResult  *res,
                                          GError       **error)
{
  return shell_session_manager_inhibitor_proxy_new_for_bus_finish (res, error);
}
